399→        {isFreePlan && (
400→          <Layout.Section>
401→            <Banner
402→              tone="info"
403→              title="Delivery rules require a paid plan"
404→              action={{
405→                content: "View pricing plans",
406→                url: "/app/pricing",
407→              }}
408→            >
409→              <p>
410→                Upgrade to the Starter plan or higher to create delivery rules
411→                with custom fees, schedules, and zone conditions.
412→              </p>
413→            </Banner>
414→          </Layout.Section>
415→        )}
416→        {hasFiniteLimit && (
417→          <Layout.Section>
418→            <InlineStack align="end">
419→              <Badge
420→                tone={
421→                  (rules as Rule[]).length >= limits.maxDeliveryRules
422→                    ? "warning"
423→                    : undefined
424→                }
425→              >
426→                {`${(rules as Rule[]).length}/${limits.maxDeliveryRules} rules used`}
