431→        <Layout.Section>
432→          <Card padding="0">
433→            {(rules as Rule[]).length === 0 ? (
434→              <EmptyState
435→                heading="No delivery rules yet"
436→                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
437→                action={{
438→                  content: "Create your first rule",
439→                  onAction: openCreate,
