  69→export const action = async ({ request }: ActionFunctionArgs) => {
  70→  const { session } = await authenticate.admin(request);
  71→  const shop = session.shop;
  72→  const formData = await request.formData();
  73→  const intent = formData.get("intent");
  74→
  75→  if (intent === "add") {
  76→    const email = String(formData.get("email") || "").trim().toLowerCase();
  77→    const zipCode = String(formData.get("zipCode") || "")
  78→      .trim()
  79→      .toUpperCase();
  80→    const note = String(formData.get("note") || "").trim() || null;
  81→
  82→    if (!email || !zipCode) return { error: "Email and zip code are required." };
  83→
  84→    const subscription = await getShopSubscription(shop);
  85→    const limits = PLAN_LIMITS[subscription.planTier];
  86→
  87→    if (limits.maxWaitlist === 0) {
  88→      return { error: "Your current plan does not include waitlist access. Upgrade to Starter or higher." };
  89→    }
  90→
  91→    if (limits.maxWaitlist < UNLIMITED) {
  92→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
  93→      if (currentCount >= limits.maxWaitlist) {
  94→        return { error: `You have reached the ${limits.maxWaitlist}-entry waitlist limit on your ${limits.label} plan. Upgrade to Pro for unlimited entries.` };
  95→      }
  96→    }
  97→
  98→    try {
  99→      await db.waitlistEntry.create({
 100→        data: { shop, email, zipCode, note },
 101→      });
 102→      return { success: true, action: "added" };
 103→    } catch {
 104→      return { error: "This email is already on the waitlist for this zip code." };
 105→    }
 106→  }
 107→
 108→  if (intent === "delete") {
 109→    const id = String(formData.get("id"));
 110→    try {
 111→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 112→      if (!existing) return { error: "Entry not found." };
 113→      await db.waitlistEntry.delete({ where: { id } });
 114→      return { success: true, action: "deleted" };
 115→    } catch {
 116→      return { error: "Failed to delete entry." };
 117→    }
 118→  }
 119→
 120→  if (intent === "update-status") {
 121→    const id = String(formData.get("id"));
 122→    const status = String(formData.get("status"));
 123→    try {
 124→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 125→      if (!existing) return { error: "Entry not found." };
 126→      await db.waitlistEntry.update({ where: { id }, data: { status } });
 127→      return { success: true, action: "updated" };
 128→    } catch {
 129→      return { error: "Failed to update entry status." };
 130→    }
 131→  }
 132→
 133→  if (intent === "bulk-notify") {
 134→    const zipCode = String(formData.get("zipCode") || "")
 135→      .trim()
 136→      .toUpperCase();
 137→    if (!zipCode) return { error: "Zip code is required." };
 138→
 139→    const bulkNotifySub = await getShopSubscription(shop);
 140→    if (PLAN_LIMITS[bulkNotifySub.planTier].maxWaitlist < UNLIMITED) {
 141→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 142→    }
 143→
 144→    const updated = await db.waitlistEntry.updateMany({
 145→      where: { shop, zipCode, status: "waiting" },
 146→      data: { status: "notified" },
 147→    });
 148→
 149→    return {
 150→      success: true,
 151→      action: "bulk-notify",
 152→      count: updated.count,
 153→      zipCode,
 154→    };
 155→  }
 156→
 157→  if (intent === "notify-zip") {
 158→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
 159→    if (!zipCode) return { error: "No ZIP code specified." };
 160→
 161→    const notifyZipSub = await getShopSubscription(shop);
 162→    if (PLAN_LIMITS[notifyZipSub.planTier].maxWaitlist < UNLIMITED) {
 163→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
 164→    }
 165→
 166→    const entries = await db.waitlistEntry.findMany({
 167→      where: { shop, zipCode, status: "waiting" },
 168→      select: { id: true, email: true },
 169→    });
 170→
 171→    if (entries.length === 0) {
 172→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
 173→    }
 174→
 175→    await db.waitlistEntry.updateMany({
 176→      where: { shop, zipCode, status: "waiting" },
 177→      data: { status: "notified" },
 178→    });
 179→
 180→    const emails = entries.map((e) => e.email);
 181→    return { action: "notify-zip", zipCode, emails, count: emails.length };
 182→  }
 183→
 184→  if (intent === "delete-all-notified") {
 185→    const deleted = await db.waitlistEntry.deleteMany({
 186→      where: { shop, status: "notified" },
 187→    });
 188→    return { success: true, action: "deleted-notified", count: deleted.count };
 189→  }
 190→
 191→  if (intent === "accept") {
 192→    const id = String(formData.get("id"));
 193→    const entry = await db.waitlistEntry.findUnique({ where: { id } });
 194→    if (!entry || entry.shop !== shop) {
 195→      return { error: "Entry not found." };
 196→    }
 197→
 198→    // Add the ZIP code to the allowed list
 199→    await db.zipCode.upsert({
 200→      where: { shop_zipCode: { shop, zipCode: entry.zipCode } },
 201→      create: {
 202→        shop,
 203→        zipCode: entry.zipCode,
 204→        type: "allowed",
 205→        isActive: true,
 206→        label: `Requested by ${entry.name || entry.email}`,
 207→      },
 208→      update: {
 209→        type: "allowed",
 210→        isActive: true,
 211→      },
 212→    });
 213→
 214→    // Mark the waitlist entry as accepted
 215→    await db.waitlistEntry.update({
 216→      where: { id },
 217→      data: { status: "accepted" },
 218→    });
 219→
 220→    return { success: true, action: "accepted", zipCode: entry.zipCode };
 221→  }
 222→
 223→  if (intent === "reject") {
 224→    const id = String(formData.get("id"));
 225→    try {
 226→      const existing = await db.waitlistEntry.findFirst({ where: { id, shop } });
 227→      if (!existing) return { error: "Entry not found." };
 228→      await db.waitlistEntry.update({
 229→        where: { id },
 230→        data: { status: "rejected" },
 231→      });
 232→      return { success: true, action: "rejected" };
 233→    } catch {
 234→      return { error: "Failed to reject entry." };
 235→    }
 236→  }
 237→
 238→  return null;
 239→};
